###################### UNIQUE EVENTS #############################################

#Function for unifying segments
unifySegments.multiple<-function(profiles,window,bin.size){
  #if input data is a QDNAseq object --> generated by Michael pipeline
  if(is(profiles,"QDNAseqCopyNumbers")==TRUE){
    samples<-colnames(profiles)
    #get copy number profiles
    segTabs<-list()
    for(i in samples){
      segTabs[[i]]<-CNpare::getSegTable(profiles[,i])
    }
    
    #unify & collapse segments within window distance
    chroms<-unique(as.character(unlist(lapply(segTabs,"[[",1))))
    new_seg<-c()
    for (c in chroms){
      starts<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        s<-as.numeric(cn[cn$chromosome==c,"start"])
      })
      ends<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        e<-as.numeric(cn[cn$chromosome==c,"end"])
        e<-sort(e,decreasing = T)
      })
      start<-max(as.numeric(unlist(lapply(starts,"[[",1))))
      end<-min(as.numeric(unlist(lapply(ends,"[[",1))))
      
      c.segTabs<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        cn<-cn[cn$chromosome==c,]
        cn[1,2]<-start
        cn[nrow(cn),3]<-end
        cn
      })
      starts<-sort(unique(as.numeric(unlist(lapply(c.segTabs,"[[",2)))))
      ends<-c(starts[-1]-1,end)
      
      #collapse segments that are within window distance
      starts_collapsed<-c()
      ends_collapsed<-c()
      if(length(starts)>1){
        for(i in 1:(length(starts)-1)){
          if(abs(starts[i+1]-starts[i])>(window+1)){
            starts_collapsed<-c(starts_collapsed,starts[i])
            ends_collapsed<-c(ends_collapsed,(starts[i+1]-1))
          }
        }
        starts_collapsed<-c(starts_collapsed,ends_collapsed[length(ends_collapsed)]+1)
        ends_collapsed<-c(ends_collapsed,ends[length(ends)])
      }else{
        starts_collapsed<-starts
        ends_collapsed<-ends
      }
      new_seg<-rbind(new_seg,cbind(chromosome=c,starts_collapsed,ends_collapsed))
    }
    
    #generate output matrix of unified copy number
    cn_out<-c()
    for(i in samples)
    {
      curr_seg<-c()
      for(j in 1:nrow(new_seg))
      {
        chr<-new_seg[j,1]
        start<-as.numeric(new_seg[j,2])
        end<-as.numeric(new_seg[j,3])
        curr_cn<-Biobase::assayDataElement(profiles[,i],"segmented")
        start_ind<-which(rownames(curr_cn)==paste0(chr,":",start,"-",as.integer(start+bin.size-1)))
        end_ind<-which(rownames(curr_cn)==paste0(chr,":",as.integer(end)-bin.size+1,"-",as.integer(end)))
        if(length(end_ind)==0)
        {
          end_ind<-which(grepl(paste0(chr,":[0-9]+-",as.integer(end)),rownames(curr_cn)))
          if(length(end_ind)==0)
          {
            end_ind<-which(rownames(curr_cn)==paste0(chr,":",end+1,"-",as.integer(end+bin.size)))
          }
        }
        curr_seg<-c(curr_seg,median(curr_cn[start_ind:end_ind,],na.rm=T))
      }
      cn_out<-cbind(cn_out,curr_seg)
    }
    colnames(cn_out)<-samples
    out<-as.data.frame(cbind(new_seg,cn_out))
    colnames(out)[1:3]<-c("chromosome","start","end")
  }
  
  #if input data is a list of copy number profiles
  else if(is(profiles,"list")==TRUE | is(profiles,"data.frame")==TRUE){
    if(is(profiles,"list")==TRUE){
      samples<-names(profiles)
      segTabs<-profiles}
    if(is(profiles,"data.frame")==TRUE){
      samples<-unique(profiles$sample)
      segTabs<-lapply(samples,function(thisSample){
        return(profiles[profiles$sample==thisSample,])
      })
    }
    
    #unify & collapse segments within window distance
    chroms<-unique(as.character(unlist(lapply(segTabs,"[[",1))))
    out<-c()
    for (c in chroms){
      starts<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        s<-as.numeric(cn[cn$chromosome==c,"start"])
      })
      ends<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        e<-as.numeric(cn[cn$chromosome==c,"end"])
        e<-sort(e,decreasing = T)
      })
      start<-max(as.numeric(unlist(lapply(starts,"[[",1))))
      end<-min(as.numeric(unlist(lapply(ends,"[[",1))))
      
      c.segTabs<-lapply(1:length(segTabs),function(thisSamp){
        cn<-segTabs[[thisSamp]]
        cn<-cn[cn$chromosome==c,]
        cn[1,2]<-start
        cn[nrow(cn),3]<-end
        cn
      })
      
      starts<-sort(unique(as.numeric(unlist(lapply(c.segTabs,"[[",2)))))
      ends<-c(starts[-1]-1,end)
      
      #collapse segments that are within window distance
      starts_collapsed<-c()
      ends_collapsed<-c()
      if(length(starts)>1){
        # check that not all the starts are within the same window to avoid neglecting all
        if(sum(starts[-1]-starts[-length(starts)] > (window+1)) > 1){
          for(i in 1:(length(starts)-1)){
            if(abs(starts[i+1]-starts[i])>(window+1)){
              starts_collapsed<-c(starts_collapsed,starts[i])
              ends_collapsed<-c(ends_collapsed,(starts[i+1]-1))
            }
          }
          starts_collapsed<-c(starts_collapsed,ends_collapsed[length(ends_collapsed)]+1)
          ends_collapsed<-c(ends_collapsed,ends[length(ends)]) 
        } else {
          starts_collapsed <- starts[1]
          ends_collapsed <- ends[length(ends)]
        }
      }else{
        starts_collapsed<-starts
        ends_collapsed<-ends
      }
      new_seg<-cbind(starts_collapsed,ends_collapsed)
      
      #generate output table with unified copy number
      c.unify<-lapply(1:length(c.segTabs),function(thisSamp){
        cn<-c.segTabs[[thisSamp]]
        cn<-cn[,c(1:4)]
        cn[,c(2:ncol(cn))]<-sapply(cn[,c(2:ncol(cn))],as.numeric)
        cn<-CNpare::getUnifiedCN(new_seg,cn)
        cn
      })
      names(c.unify)<-samples
      c.unify<-do.call(cbind,c.unify)
      c.unify<-as.data.frame(cbind(c,new_seg,c.unify))
      colnames(c.unify)[1:3]<-c("chromosome","start","end")
      out<-rbind(out,c.unify)
    }
  }
  
  #input file is wrong --> print an error to know the problem
  else{
    print("Error in input file! Input file must be a QDNAseqCopyNumbers object or a list of profiles")
  }
  out[,c(2:ncol(out))]<-sapply(out[,c(2:ncol(out))],as.numeric)
  out<-out[order(factor(out$chromosome,levels=chroms),out$start),]
  return(out)
}



#Function for getting unique events per cell
uniqueEvents.multiple<-function(unify.matrix, reference=FALSE){
  #Round absolute copy-number of segments in all cells
  ncells=c(4:ncol(unify.matrix))
  segVals<-as.matrix(unify.matrix[,ncells])
  
  if(reference==FALSE){
    #Get matrix with logical values indicating if it's a shared or unique event
    shared.matrix=c()
    for(thisSeg in 1:nrow(segVals)){
      cnseg<-as.vector(segVals[thisSeg,])
      shared<-duplicated(cnseg) | duplicated(cnseg, fromLast = TRUE)
      shared.matrix=rbind(shared.matrix,shared)
    }
    colnames(shared.matrix)<-colnames(segVals)
  } else{
    reference=segVals[,1]
    #Get matrix with logical values indicating if it's a shared or unique event
    shared.matrix=c()
    for(thisSamp in 1:ncol(segVals)){
      shared<-reference==segVals[,thisSamp]
      shared.matrix=cbind(shared.matrix,shared)
    }
    colnames(shared.matrix)<-colnames(segVals)
  }
  
  #Get events per cell classified as unique or shared
  cells=colnames(segVals)
  if(length(cells)<=10){
    colors=c("#AAD34F","#BB44CC","#F8B385","#D5C1CC","#E1F3C9",
             "#97F0A9","#90E9E9","#E99ABE","#8EA2C2","#B89EF2")
    colors=colors[1:length(cells)]
  }else{
    colors=rep("#D55E00",length(cells))
  }
  
  lEvents=lapply(cells,function(thisCell){
    cols=c("chromosome","start","end",thisCell)
    events=unify.matrix[,c("chromosome","start","end",thisCell)]
    events$color="grey30"
    events[which(shared.matrix[,thisCell]==FALSE),"color"]<-colors[which(cells==thisCell)]
    colnames(events)[4]<-"segVal"
    chroms=c(1:22,"X") #remove Y chromosome
    events<-events[events$chromosome%in%chroms,]
    events
  })
  names(lEvents)<-cells
  return(lEvents)
}


#Function for classifying copy number alterations per cell
classEvents.sc<-function(unify.matrix,threshold){
    #Round absolute copy-number of segments in all cells
    ncells=c(4:ncol(unify.matrix))
    segVals<-as.matrix(unify.matrix[,ncells])
    
    #Get matrix with logical values indicating if it's a shared or unique event
    shared.matrix=c()
    for(thisSeg in 1:nrow(segVals)){
        cnseg<-as.vector(segVals[thisSeg,])
        vals<-as.data.table(table(cnseg))
        vals$cnseg<-as.numeric(vals$cnseg)
        vals$freq<-vals$N/length(cnseg)
        vals$class<-ifelse(vals$N==1,"unique",ifelse(vals$freq>threshold,"clonal","subclonal"))
        dat=as.data.frame(cnseg)
        dat=left_join(dat,vals[,c(1,4)],by="cnseg")
        shared.matrix=rbind(shared.matrix,dat$class)
    }
    colnames(shared.matrix)<-colnames(segVals)
    
    #Prepare outputs
    cells=colnames(segVals)
    lEvents=lapply(cells,function(thisCell){
        cols=c("chromosome","start","end",thisCell)
        events=unify.matrix[,c("chromosome","start","end",thisCell)]
        events$class=shared.matrix[,thisCell]
        colnames(events)[4]<-"segVal"
        chroms=c(1:22,"X") #remove Y chromosome
        events<-events[events$chromosome%in%chroms,]
        events
    })
    names(lEvents)<-cells
    return(lEvents)
}


#Function for plotting unique events
CNplot_uniqueEvents.multiple<-function(unify.matrix,reference=FALSE,legend=FALSE){
  ##Prepare data for plotting
  lEvents=uniqueEvents.multiple(unify.matrix,reference=reference)
  
  ##Plotting
  #prepare length of each chr
  chr_sizes <- CNpare:::chr_sizes
  chr_sizes$length <- 1e-6*chr_sizes$length #Convert sizes to Mb
  chr_sizes$offset <- cumsum(chr_sizes$length)-chr_sizes$length #Calculate the interval range of each chr
  
  #get ref profile for defining plotting area
  events<-CNpare::CNconvert(lEvents[[1]],chr_sizes)
  
  #plot
  plot.new()
  plot.window(xlim=c(0,sum(events$length)),ylim=c(0,10),yaxs="i",xaxs="r")
  abline(v=chr_sizes$offset,lty=2,lwd=1)
  abline(v=0,lty=1,lwd=1)
  
  #title
  title(main="Copy Number Profile",
        xlab="Chromosome",ylab="Copy Number",
        cex.lab=1.1,cex.main=1.5, font.lab=2, outer=FALSE)
  
  #legend
  if(legend==FALSE){
    legend(x="topright", legend="shared events", fill="gray30", cex=0.5, bty="n", xpd=TRUE, inset=c(-0.05,-0.2))
  }
  if(legend==TRUE){
    #get colors and names for legend
    legend=cbind(name="shared",color="grey30")
    for(cell in names(lEvents)){
      col=unique(lEvents[[cell]][,"color"])[unique(lEvents[[cell]][,"color"])!="grey30"]
      if(length(col)==0){col="grey30"}
      legend=rbind(legend,cbind(name=cell,color=col))
    }
    legend(x="topright", legend=legend[,1], fill=legend[,2], cex=0.5, bty="n", xpd=TRUE, inset=c(-0.05,-0.2))
  }
  
  #set the axis
  axis(1, labels=c(seq_len(22),"X"), tick=TRUE, at = chr_sizes$offset+chr_sizes$length/2,cex.axis=1)
  
  lablist<-as.vector(c(0:10))
  text(par("usr")[4], seq(0, 10, by=1), labels=lablist, srt=0, pos=2, xpd=TRUE, offset=1, cex=1.3)
  
  #plot the first data set
  for(thisCell in 1:length(lEvents)){
    events<-CNpare::CNconvert(lEvents[[thisCell]],chr_sizes)
    for (i in seq_len(nrow(events))){
      e <- events[i,]
      segments(e$start,e$segVal,e$end,e$segVal,lwd=2.,col=e$color)
    }
  }
}

#Function for plotting unique events per chromosome
CNplot_uniqueEvents_chr.multiple<-function(unify.matrix,chr,reference=FALSE,legend=FALSE){
  ##Prepare data for plotting
  lEvents=uniqueEvents.multiple(unify.matrix,reference=reference)
  
  ##Plotting
  #prepare length of each chr
  chr_sizes <- CNpare:::chr_sizes
  chr_sizes$length <- 1e-6*chr_sizes$length #Convert sizes to Mb
  chr_sizes$offset <- cumsum(chr_sizes$length)-chr_sizes$length #Calculate the interval range of each chr
  
  #get ref profile for defining plotting area
  events<-lEvents[[1]]
  events<-CNpare::CNconvert(events[events[,1]==chr,],chr_sizes)
  
  #plot
  plot.new()
  plot.window(xlim=c(events$start[1],events$end[nrow(events)]),
              ylim=c(0,10),yaxs="i",xaxs="r")
  abline(v=events$end[nrow(events)],lty=2,lwd=1)
  abline(v=events$start[1],lty=1,lwd=1)
  
  #title
  title(main="Copy Number Profile",
        xlab=paste0("Chromosome ",chr),ylab="Copy Number",
        cex.lab=1.1,cex.main=1.5,font.lab=2,outer=FALSE)
  
  #legend
  if(legend==FALSE){
    legend(x="topright", legend="shared events", fill="gray30", cex=0.5, bty="n", xpd=TRUE, inset=c(-0.05,-0.2))
  }
  if(legend==TRUE){
    #get colors and names for legend
    legend=cbind(name="shared",color="grey30")
    for(cell in names(lEvents)){
      col=unique(lEvents[[cell]][,"color"])[unique(lEvents[[cell]][,"color"])!="grey30"]
      if(length(col)==0){col="grey30"}
      legend=rbind(legend,cbind(name=cell,color=col))
    }
    legend(x="topright", legend=legend[,1], fill=legend[,2], cex=0.5, bty="n", xpd=TRUE, inset=c(-0.05,-0.2))
  }
  
  #set the axis
  lablist<-as.vector(c(0:10))
  text(events$start[1], seq(0, 10, by=1), labels=lablist, srt=0, pos=2,
       xpd=TRUE, offset=1, cex=1.3)
  
  #plot segments of each cell
  for(thisCell in 1:length(lEvents)){
    events<-lEvents[[thisCell]]
    events<-CNpare::CNconvert(events[events[,1]==chr,],chr_sizes)
    for (i in seq_len(nrow(events))){
      e <- events[i,]
      segments(e$start,round(e$segVal),e$end,round(e$segVal),lwd=2.,col=e$color)
    }
  }
}


# ADAPTATION FROM ANGEL
# FUNCTION TO PLOT CNPROFILES FROM MULTIPLE SAMPLES SIMULTANEOUSLY
# THIS WAS ADAPTED FROM BARBARA'S CNPARE FUNCTIONS
CNPlot_MultSamps <- function(lProfiles){
  
  ##Plotting
  #data for plotting
  chr_sizes <- CNpare:::chr_sizes
  chr_sizes$length <- 1e-6 * chr_sizes$length #Convert sizes to Mb
  chr_sizes$offset <- cumsum(chr_sizes$length) - chr_sizes$length #Calculate the interval range of each chr
  
  # plot
  
  #plot
  plot.new()
  plot.window(xlim=c(0,sum(chr_sizes$length)),ylim=c(0,10),yaxs="i",xaxs="r")
  abline(v=chr_sizes$offset,lty=2,lwd=1)
  abline(v=0,lty=1,lwd=1)
  
  
  #title
  title(main="Copy Number Profile All Samples",
        xlab="Chromosome",ylab="Copy Number",
        cex.lab=1.1,cex.main=1.5, font.lab=2, outer=FALSE)
  
  
  #set the axis
  axis(1, labels=c(seq_len(22),"X"), tick=TRUE, at = chr_sizes$offset+chr_sizes$length/2,cex.axis=1)
  
  lablist<-as.vector(c(0:10))
  text(par("usr")[4], seq(0, 10, by=1), labels=lablist, srt=0, pos=2, xpd=TRUE, offset=1, cex=1.3)
  
  colors=c("#AAD34F","#BB44CC","#F8B385","#D5C1CC","#E1F3C9",
           "#97F0A9","#90E9E9","#E99ABE","#8EA2C2","#B89EF2")
  #plot the first data set
  for(thisSamp in 1:length(lProfiles)){
    events<-CNpare::CNconvert(lProfiles[[thisSamp]],chr_sizes)
    for (i in seq_len(nrow(events))){
      e <- events[i,]
      segments(e$start,e$segVal,e$end,e$segVal,lwd=2.,col=colors[thisSamp])
    }
  }
}


